// Generated by hand against the Phosphor catalog — verify names when upgrading @phosphor-icons/react.

/** Icon + tint art direction for category tiles, pins, and card fallbacks. */
export interface CategoryArt {
  /** Exact named export from @phosphor-icons/react (e.g. "Wrench", "Scales"). */
  icon: string;
  /** Group tint token suffix — resolves to --tint-{tint} CSS vars. */
  tint: string;
}

/**
 * One tint family per category group, keyed by group slug.
 * The key doubles as the tint token suffix (--tint-home-property, etc.);
 * a --tint-neutral pair must also exist in CSS for the fallback.
 * Hues are muted/editorial and sit comfortably next to the navy/teal/orange brand:
 * `light` is a tile background for a dark icon, `dark` a tile background for a light icon.
 */
export const GROUP_TINTS: Record<string, { name: string; light: string; dark: string }> = {
  "home-property": { name: "Terracotta", light: "hsl(18, 42%, 89%)", dark: "hsl(18, 30%, 24%)" },
  auto: { name: "Steel", light: "hsl(202, 14%, 87%)", dark: "hsl(202, 11%, 25%)" },
  "food-drink": { name: "Amber", light: "hsl(38, 55%, 87%)", dark: "hsl(38, 32%, 22%)" },
  "health-medical": { name: "Teal", light: "hsl(168, 34%, 87%)", dark: "hsl(168, 28%, 20%)" },
  "beauty-personal-care": { name: "Rose", light: "hsl(345, 36%, 91%)", dark: "hsl(345, 22%, 24%)" },
  "professional-financial": { name: "Slate", light: "hsl(226, 28%, 89%)", dark: "hsl(226, 22%, 24%)" },
  retail: { name: "Plum", light: "hsl(285, 24%, 90%)", dark: "hsl(285, 18%, 24%)" },
  "family-education-community": { name: "Gold", light: "hsl(47, 48%, 87%)", dark: "hsl(46, 30%, 21%)" },
};

